declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\LiveDisplaySessionService;Auth::requireAdmin();header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);echo json_encode(['ok'=>false,'error'=>'Invalid request.']);exit;}$pdo=Database::connection();$eventId=(int)($_POST['event_id']??0);$test=($_POST['data_mode']??'real')==='test';$userId=(int)(Auth::user()['id']??0);try{$session=LiveDisplaySessionService::forEvent($pdo,$eventId,$test);if(!$session){http_response_code(409);echo json_encode(['ok'=>false,'error'=>'Generate the Live Display link first.']);exit;}$action=(string)($_POST['action']??'update');if($action==='unlock_results'){$session=LiveDisplaySessionService::setResultsUnlocked($pdo,$eventId,$test,true,$userId);}elseif($action==='lock_results'){$session=LiveDisplaySessionService::setResultsUnlocked($pdo,$eventId,$test,false,$userId);}else{$session=LiveDisplaySessionService::update($pdo,$eventId,$test,$_POST,$userId);}echo json_encode(['ok'=>true,'session'=>['screen_type'=>$session['screen_type']??'holding','reveal_place'=>$session['reveal_place']??null,'page_number'=>(int)($session['page_number']??1),'auto_page'=>(bool)($session['auto_page']??false),'page_delay_seconds'=>(int)($session['page_delay_seconds']??30),'loop_enabled'=>(bool)($session['loop_enabled']??false),'loop_screens'=>$session['loop_screens']??'','loop_delay_seconds'=>(int)($session['loop_delay_seconds']??15),'results_unlocked'=>(bool)($session['results_unlocked']??false),'state_version'=>(int)($session['state_version']??0)]],JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}
